<script setup lang="ts">
import { ref, watch } from 'vue';
import { Link, useForm, usePage } from '@inertiajs/vue3';
import ConfirmDialog from './ConfirmDialog.vue';
import InvoiceAmounts from './InvoiceAmounts.vue';
import InvoiceJournal from './InvoiceJournal.vue';
import { money, type Snapshot, type Journal } from '../types/salesOrder';
import { useConfirmedMutation } from '../composables/confirmedMutation';
const confirmation = useConfirmedMutation();
const { pending: confirming } = confirmation;
type InvoiceRow = { id: number; nomor: string; tanggal: string; no_faktur: string | null; perlakuan_ppn: string; status: string; batal_alasan?: string; batal_date?: string; tanggal_bayar: string | null; keterangan_bayar: string | null; penjualan: string; dpp: string; ppn: string; biaya_lain: string; total_tagihan: string; piutang: string };
const props = defineProps<{ invoice: InvoiceRow; snapshot: Snapshot; journal: Journal[]; setor: { tanggal: string; nomor: string | null } | null; canManage: boolean; today: string; initialAction?: string }>();
const emit=defineEmits<{saved:[];busy:[value:boolean]}>();
const eligible = (value?:string) => props.canManage && props.invoice.status==='invoiced' && (value==='pembayaran' ? !props.invoice.tanggal_bayar : value==='bukti-setor' && props.invoice.perlakuan_ppn==='WAPU' && BigInt(props.invoice.ppn)>0n && !props.setor);
const action = ref(eligible(props.initialAction) ? props.initialAction || '' : '');
const form = useForm({ tanggal: props.today, keterangan: '', nomor: '' });
watch(()=>form.processing || confirming.value,value=>emit('busy',value),{immediate:true});

const page = usePage();
const allowed = (menu: string) => ((page.props.permissions as Record<string, string[]>)?.[menu] || []).includes('View');
const save = () => confirmation.form(form, 'post', `/invoicing/${props.invoice.id}/${action.value}`, { title: action.value === 'pembayaran' ? 'Catat pelunasan penuh?' : 'Terima bukti setor WAPU?', text: `${props.invoice.nomor}: ${money(action.value === 'pembayaran' ? props.invoice.piutang : props.invoice.ppn)}. Pencatatan satu kali dan tidak dapat diedit.`, danger: true }, { preserveScroll: true, onSuccess: () => { action.value = ''; form.reset(); emit('saved'); } });
</script>
<template><div class="invoice-detail">
        <div class="row-actions"><a :href="`/invoicing/${invoice.id}/pdf`" target="_blank" rel="noopener">Print Invoice</a><button v-if="canManage && !invoice.tanggal_bayar && invoice.status === 'invoiced'" type="button" @click="action = 'pembayaran'; form.clearErrors()">Catat Pembayaran</button><button v-if="canManage && invoice.status === 'invoiced' && invoice.perlakuan_ppn === 'WAPU' && BigInt(invoice.ppn) > 0n && !setor" type="button" @click="action = 'bukti-setor'; form.clearErrors()">Terima Bukti Setor WAPU</button></div>
        <section v-if="invoice.status === 'batal'" class="panel" role="status"><h2>Invoice Batal</h2><p>{{ invoice.batal_date }}: {{ invoice.batal_alasan }}</p><p>Nilai dan jurnal historis tetap tersimpan. Pembalikan jurnal dilakukan manual.</p></section><section class="panel"><h2>Header</h2><p>Kepada: {{ snapshot.quotation.kepada_nama }} · u.p. {{ snapshot.quotation.up_nama }}</p><p>{{ snapshot.quotation.alamat }}</p><p>{{ snapshot.company?.npwp }}</p><p>Tanggal Invoice: {{ invoice.tanggal }} · Faktur: {{ invoice.no_faktur || '—' }} · {{ invoice.perlakuan_ppn }}{{ !snapshot.quotation.is_ppn ? ' · Tanpa PPN' : '' }}</p><p>{{ snapshot.program.nomor }} · {{ snapshot.program.jenis.toUpperCase() }} · {{ snapshot.judul }}</p><p>{{ snapshot.program.tgl_mulai }} s.d. {{ snapshot.program.tgl_selesai }} · {{ snapshot.program.waktu }} · {{ snapshot.program.lokasi }}</p><div class="row-actions"><Link v-if="allowed('sales_order')" :href="`/sales-order/${snapshot.so.id}`">{{ snapshot.so.nomor }}</Link><span v-else>{{ snapshot.so.nomor }}</span><Link v-if="allowed('quotation_program')" :href="`/quotation/${snapshot.quotation.id}`">{{ snapshot.quotation.nomor }}</Link><span v-else>{{ snapshot.quotation.nomor }}</span></div></section>
        <section class="panel"><h2>Rincian Tagihan</h2><p>{{ snapshot.quotation.skema_harga === 'allin' ? 'All-in 1 company' : 'Satu Invoice per SO' }} · {{ snapshot.peserta.length }} peserta Deal</p><p v-for="p in snapshot.peserta" :key="p.id">{{ p.nama }} · {{ p.instansi }}</p><p>Harga {{ money(snapshot.quotation.skema_harga === 'allin' ? snapshot.quotation.harga_allin : snapshot.quotation.harga_peserta) }} · Diskon {{ money(snapshot.quotation.diskon) }}</p><InvoiceAmounts :amounts="{ penjualan: invoice.penjualan, dpp: invoice.dpp, ppn: invoice.ppn, biaya_lain: invoice.biaya_lain, total_tagihan: invoice.total_tagihan, piutang: invoice.piutang }" :treatment="invoice.perlakuan_ppn" :taxed="!!snapshot.quotation.is_ppn" /></section>
        <section class="panel"><h2>Jurnal Invoice &amp; Bukti Setor</h2><InvoiceJournal :rows="journal" :program="snapshot.program.nomor" /><p v-if="setor">Bukti setor: {{ setor.tanggal }} · {{ setor.nomor || 'Tanpa nomor' }}</p><p v-if="invoice.tanggal_bayar">Lunas penuh {{ money(invoice.piutang) }} · {{ invoice.tanggal_bayar }} · {{ invoice.keterangan_bayar }}</p></section>
        <ConfirmDialog v-if="action" :title="action === 'pembayaran' ? 'Catat pelunasan penuh?' : 'Terima bukti setor WAPU?'" confirm-label="Simpan" :busy="form.processing || confirming" @confirm="save" @cancel="action = ''"><p>{{ invoice.nomor }} · {{ money(action === 'pembayaran' ? invoice.piutang : invoice.ppn) }}</p><p>Pencatatan satu kali dan tidak dapat diedit.</p><label>Tanggal<input v-model="form.tanggal" type="date" :max="today" required /></label><label v-if="action === 'pembayaran'">Keterangan<input v-model="form.keterangan" maxlength="100" /></label><label v-else>Nomor bukti setor (opsional)<input v-model="form.nomor" maxlength="100" /></label><p v-for="e in form.errors" :key="e" class="error" role="alert">{{ e }}</p></ConfirmDialog>
</div></template>
